try {
!function(){var e=window,t=(document,e.GGSX_PAGES=e.GGSX_PAGES||{});t.pages=t.pages||{},t.blocks=t.blocks||{};var o="/shop-now",a="https://wa.me/590690779119?text="+encodeURIComponent("Hi GrocerGoSx, I'd like my villa stocked before I arrive. Here's my list:");t.pages["/villa-stocking"]={blocks:[{type:"hero",img:"85c3c2_6612e101d1b047ffbc3abfbaa2b3b707~mv2.jpg",alt:"A stocked villa kitchen with fresh fruit and an ocean view",eyebrow:"Pre-arrival villa stocking",title:"Arrive to a fully stocked villa.",lead:"Send your list before you fly. We shop the island's best markets, deliver to your villa and put everything away, so your first evening starts with a cold drink instead of a supermarket run.",ctas:[{t:"Stock my villa",href:o},{t:"See ready-made kits",href:"/stocking-packages"}],chips:["Nothing charged today","Fridge & freezer put away","Photo when it's done","Dutch & French side"]},{type:"split",img:"11062b_0326238ca4f3477ea16f44a2108280d7~mv2.jpg",alt:"Grocery bags unpacked on a kitchen counter",kicker:"What's included",title:"Everything ready before you check in",text:["You land, collect the keys and the kitchen is already done. Every stocking includes:"],items:["Shopping on delivery day at the island's best markets","Delivery before check-in to your villa, condo or rental","Fridge, freezer and pantry put away, with your host's OK","A photo of your stocked kitchen when we're done","The closest match if something's unavailable, or a message first, your choice","Beer, wine, spirits and ice on request (18+)"]},{type:"steps",title:"How it works",sub:"Four steps, and about two minutes of your time.",items:[["Fill your basket","Shop 3,000+ items, add a [ready-made kit](/stocking-packages) or [message us your list]("+a+"). No list yet? We'll send you a starter list."],["Check out with your arrival details","Your villa, arrival date and a delivery window that ends before check-in, plus your host's contact. Nothing is charged at checkout."],["We confirm by message","We check the list with you and send your total with a secure payment link before we shop."],["We shop, stock and send a photo","On delivery day we shop, put everything away and send you a photo of your kitchen."]]},{type:"prices",title:"Simple, all-in pricing",sub:"The same pricing as every GrocerGoSx order. All prices include applicable taxes.",rows:[["Groceries","GrocerGoSx concierge prices","About {{catalogue_markup}} over the shelf price ({{liquor_markup}} on beer, wine and spirits), which covers choosing, buying and the time in-store. On the part of a till receipt above $300, 15%."],["Service Fee","{{run_rate}} of your order","{{Fee_limits}}, put-away included. Pre-arrival stockings start from $150 of groceries."],["Delivery","{{delivery_value}}","{{Delivery_how}}. Anywhere on the island."],["Taxes","Included","Nothing extra is added at checkout, and nothing is added after your quote."]],foot:"Nothing is charged at checkout. You get your confirmed total and a payment link before we shop.",link:["Full pricing & fees","/pricing"]},{type:"kits",title:"Or start from a ready-made kit",sub:"Add a kit or two to your basket and we'll stock them with the rest of your order.",ids:["g3064","g3061","g3063"],all:!0},{type:"quotes",title:"From villa owners and guests",items:[["Excellent service. Dwayne confirmed items requested were correct by sending photos and delivered exactly as requested in a timely fashion. Definitely recommend for any villa stay!","Diana McKennon","Villa property owner"],["I had a great experience with GrocerGoSx! We needed groceries for our Airbnb last minute, and they responded right away. The ordering process was quick and efficient, and our groceries were delivered within just a couple of hours.","Carmen Estevez","Villa guest"]]},{type:"faq",title:"Questions before you book",items:[["How far ahead should I book?","As soon as your dates are set. In high season, booking early gets you the delivery window you want. Arriving sooner than that? Message us and we'll do our best."],["Who lets you into the villa?","Your host or property manager. Add who to contact (or how to get in) to your checkout notes, and we arrange access before you arrive. We only go in with their authorisation."],["Do you stock villas on the French side?","Yes, anywhere on the island: {{delivery_anywhere}}. [Check your area](/service-area)."],["What if something isn't available?","Island supply varies. We pick the closest match or message you first, whichever you prefer, or remove the item and refund the difference."],["When do I pay?","Not at checkout. We confirm your total by message and send a secure payment link before we shop."],["Can you add drinks and spirits?","Yes: beer, wine, spirits, mixers and ice. Alcohol is supplied only to guests aged 18 or over."]]},{type:"cta",title:"Your villa, stocked before you land.",text:"Fill your basket and check out in about two minutes; nothing is charged today. Prefer to chat? WhatsApp, iMessage or text +590 690 77 9119.",ctas:[{t:"Stock my villa",href:o},{t:"Message us",wa:"Hi GrocerGoSx, I'd like my villa stocked before I arrive."}]}]},t.pages["/stocking-packages"]={blocks:[{type:"hero",img:"11062b_a0dfd705a83f46f2a1e461b6045be754~mv2.jpg",alt:"A basket of groceries on an orange background",eyebrow:"Stocking packages",title:"Ready-made kits for arrival day.",lead:"Pick a kit, or a few, and we'll have them waiting in your villa. Every kit is shopped on delivery day, and you can top it up with anything from the shop.",ctas:[{t:"Browse the kits",href:"#kits"},{t:"Send your own list",href:"/villa-stocking"}],chips:["Shopped on delivery day","Put away before you arrive","Top up with 3,000+ items","Taxes included"]},{type:"kits",id:"kits",title:"Choose your kits",sub:"Kit prices cover the goods. The service fee is added to the order, the same as any grocery order: {{run_rates}}, {{with_delivery}}."},{type:"steps",title:"How kits work",items:[["Add kits to your basket","Mix and match kits, then add anything else you need from the [shop](/shop-now)."],["Check out with your arrival details","Your villa, arrival date and delivery window. Add your host's contact in the notes so we can arrange access."],["We confirm by message","We check the order with you and send your total with a secure payment link before we shop."],["Waiting when you arrive","Delivered before check-in and put away with your host's OK."]]},{type:"split",flip:!0,img:"11062b_0508673a9f874b39a60b7c873455f00c~mv2.jpg",alt:"A villa pool at dusk",kicker:"Prefer it tailored?",title:"Your list, your brands",text:["Kits are a quick start. If you'd rather choose every item yourself, shop the full catalogue or send us your own list, with your favourite brands and any dietary needs."],ctas:[{t:"Villa stocking",href:"/villa-stocking"},{t:"Shop groceries",href:"/shop-now"}]},{type:"faq",title:"Good to know",items:[["Can I change what's in a kit?","Yes. Add a note at checkout to swap, remove or add items, and we'll confirm the changes with you before we shop."],["Do kit prices include the service fee?","Kit prices cover the goods. The {{run_rate}} service fee ({{fee_min_short}}) is added to the order {{with_delivery}}, and all prices include applicable taxes. [See pricing](/pricing)."],["What if an item in a kit is unavailable?","We replace it with the closest match or message you first, your choice, and refund the difference if anything is left out."],["Can kits be delivered during my stay?","Of course. Pick any delivery date and window at checkout."]]},{type:"cta",title:"Not sure what you'll need?",text:"Tell us how many guests and how long you're staying, and we'll suggest the right mix.",ctas:[{t:"Message us",wa:"Hi GrocerGoSx, can you suggest stocking kits for our stay? We are … guests for … nights."},{t:"View basket",href:"/shop-now#basket"}]}]},t.run&&t.run()}();
} catch (e) { try { console.warn('[GGSX bundle] Pages 3 Texts: Villa Stocking & Packages', e); } catch (e2) {} }
__ggsxE("4535b87e-8cb0-41c5-a02c-b4f6f7fe5dd6#0");

/* ===== GrocerGoSx Pages 5 Texts: Pricing & Service Area (1da7615f-93f9-4952-af04-df827390463a, rev 18) ===== */
__ggsxB("1da7615f-93f9-4952-af04-df827390463a#0");
try {
!function(){var e=window,r=(document,e.GGSX_PAGES=e.GGSX_PAGES||{});r.pages=r.pages||{},r.blocks=r.blocks||{},r.pages["/pricing"]={blocks:[{type:"hero",eyebrow:"Pricing & fees",title:"Clear pricing. No surprises.",lead:"Every price on GrocerGoSx already includes applicable taxes, and {{delivery_anywhere}}. Here's exactly how your total is worked out.",ctas:[{t:"Estimate your total",href:"#estimate"},{t:"Shop groceries",href:"/shop-now"}],chips:["Taxes included","{{Delivery_chip}} island-wide","Every fee in your quote","Shopping bags on us"]},{type:"prices",title:"Groceries, stocking and pickups",sub:"How every grocery, villa stocking and restaurant pickup total is built: your items plus {{fee_and_delivery}}. Nothing is added after your quote.",rows:[["Groceries & supermarket items","GrocerGoSx concierge prices","About {{catalogue_markup}} over the shelf price ({{liquor_markup}} on beer, wine and spirits). That covers choosing, buying and the time in-store, and the price you see in the shop is the price you pay."],["Large stockings","15% over the shelf above $300","On the part of a till receipt above $300, groceries are charged at 15% over the shelf instead of {{catalogue_markup}}. It shows as its own line on your invoice."],["Minimum basket","{{min_order}}","Shop orders need {{min_order}} of items in the basket, taxes included. Restaurant pickups and errands have no minimum."],["Service Fee","{{run_rate}} of your order","For shopping, selection and handling: {{fee_limits}}. Standing orders, regulars and guests of our partner properties count as booked ahead. {{Delivery_sentence}}."],["Delivery Fee","{{delivery_value}}","Anywhere on the island, Dutch or French side, once per run, however many stops. {{Delivery_how_full}}."],["Taxes","Included","All prices and fees already include applicable taxes, so no tax is added at checkout."],["Restaurant pickup","Menu price + {{service_fee_rate}} service fee","Your food at the restaurant's menu price, with the restaurant's receipt, plus the {{service_fee_rate}} service fee for ordering, paying and carrying. On a grocery run each restaurant adds {{restaurant_pickup_fee}} delivery/waiting time. On its own, a restaurant order has a {{restaurant_only_fee}} minimum fee ({{restaurant_only_fee_french}} when the French side is involved) and a {{restaurant_only_delivery}} delivery fee; each extra restaurant adds {{restaurant_pickup_fee}}."]]},{type:"prices",title:"Errands and other services",rows:[["Errands & bill payments","Cost + {{run_rate}} service fee","Whatever we pay for you, a bill, a named item or a pickup, is passed on at exact cost with the receipt, plus the {{run_rate}} service fee ({{fee_min_short}}, {{delivery_short}}). Or a {{errand_stop_fee}} extra stop on a grocery or pickup run."],["Pharmacy","Receipt + {{run_rate}} service fee","Charged as an errand: the {{run_rate}} service fee ({{fee_min_short}}, {{delivery_short}}) on its own, or a {{errand_stop_fee}} extra stop on a grocery or pickup run. Prescriptions welcome."],["Laundry, wash & fold","{{laundry_per_lb}} per lb + {{laundry_fee_each_way}} each way","Weighed at pickup, then collected and returned with your grocery or pickup orders (as an add-on to a run)."],["Late Night Snack Run","$65 late-night fee + your items","Thursday to Saturday, 9:00–11:00 PM; order by 9:30 PM. Items at GrocerGoSx prices, from $50 of items. The $65 covers the run and delivery, with no Service Fee on top."],["Rentals","Rental price + {{run_rate}} service fee","Coolers and folding tables for up to 3 days or by the week, delivered on your start date, {{delivery_short}}, and collected at the end for {{rental_collection}}. Chairs, umbrellas, cribs and strollers on request. [See rentals](/rentals)"],["Custom requests","Quoted from the same pieces","The {{run_rate}} service fee on what we buy for you ({{delivery_short}}) and any extra stops. Nothing is booked or purchased until you approve the total."]]},{type:"calc",id:"estimate",title:"Estimate your total",sub:"A quick estimate for a grocery, stocking or pickup run. Groceries at GrocerGoSx prices, restaurant food at the menu price."},{type:"cards",title:"How you pay",cols:3,items:[{icon:"chat",t:"Confirmed before we shop",x:"Nothing is charged when you check out or send a list. We confirm your total by message first; on a first order over $300 we take a card hold or a 50% deposit."},{icon:"shield",t:"Secure payment link",x:"Pay by card through a secure link before we shop or dispatch, or by transfer or cash: the same price either way. All prices are in US dollars."},{icon:"receipt",t:"Receipts and invoices",x:"Pass-through items come with the receipt, and every order gets an itemised invoice."}]},{type:"faq",title:"Substitutions, refunds and the fine print",items:[["What if an item is unavailable?","Island supply varies. We offer the closest substitute or remove the item and refund the difference, and we message you before substituting anything unusual."],["Something arrived damaged or missing?","Message us within 24 hours of delivery with a photo, and we'll replace the item on the next run or refund it, your choice."],["Can I cancel?","Cancellations before we start shopping are refunded in full. Once shopping has started, the goods already purchased are charged."],["How is the service fee worked out?","It's {{run_rate}} of your order, {{fee_limits}}. The minimum covers the time and drive every run takes; the cap keeps big villa stockings from overpaying. {{Delivery_faq}}."],["Is there a minimum order?","Yes: a shop basket needs at least {{min_order}} of items, taxes included; restaurant pickups and errands have no minimum. Pre-arrival stockings start from $150 of groceries and the Late Night Snack Run from $50 of items."],["Do you charge for bags?","No. Shopping bags are on us."],["Can you deliver alcohol?","Yes. Wine, beer and spirits are supplied only to adults aged 18 or over, and valid ID may be requested on delivery."]]},{type:"cta",title:"Ready when you are.",text:"Fill a basket, stock your villa before you land, or just send us your list.",ctas:[{t:"Shop groceries",href:"/shop-now"},{t:"Send your list",wa:"Hi GrocerGoSx, here's my list: "}]}]},r.pages["/service-area"]={blocks:[{type:"hero",img:"895d4dc89f5e473ba1e2c390095fdf89.jpg",alt:"A Caribbean beach with palm trees and green hills",eyebrow:"Service area",title:"One island, both sides, {{delivery_chip}}.",lead:"We deliver to villas, condos, hotels and marinas across Dutch Sint Maarten and French Saint-Martin. {{Delivery_anywhere}}; find your area to see which side you're on.",ctas:[{t:"Find your area",href:"#find"},{t:"Shop groceries",href:"/shop-now"}],chips:["{{Delivery_chip}}, Dutch side","{{Delivery_chip_fr}}, French side","Daily, 8:30 AM – 11 PM"]},{type:"areas",id:"find",title:"Find your area",sub:"Type your area, resort, hotel or marina to see your side of the island."},{type:"cards",title:"Good to know",cols:4,items:[{icon:"clock",t:"Delivery windows",x:"Daily from 8:30 AM to 11 PM. We shop on your delivery day, in supermarket hours: order by 6 PM for delivery today (by noon on Sundays)."},{icon:"star",t:"Late-night runs",x:"Thursday to Saturday, 9:00–11:00 PM, Dutch side to start. French side on request.",href:"https://wa.me/590690779119?text="+encodeURIComponent("Hi GrocerGoSx, I'd like a Late Night Snack Run."),more:"Order a snack run"},{icon:"map",t:"High season",x:"Island traffic can be heavy in high season, so we plan runs by side of the island. Booking ahead gets you the window you want."},{icon:"boat",t:"Marinas",x:"We deliver to the main marinas on both sides of the island.",href:"/yacht-provisioning",more:"Yacht provisioning"}]},{type:"cta",title:"Staying somewhere we haven't listed?",text:"Send us the address and we'll confirm your side of the island.",ctas:[{t:"Message us",wa:"Hi GrocerGoSx, can you deliver to: "},{t:"Shop groceries",href:"/shop-now"}]}]},r.run&&r.run()}();
} catch (e) { try { console.warn('[GGSX bundle] Pages 5 Texts: Pricing & Service Area', e); } catch (e2) {} }
__ggsxE("1da7615f-93f9-4952-af04-df827390463a#0");

/* ===== GrocerGoSx Pages 4 Texts: Yacht & Partners (d63d0170-b5a8-437c-88dc-994a121cc99c, rev 11) ===== */
__ggsxB("d63d0170-b5a8-437c-88dc-994a121cc99c#0");
try {
!function(){var e=window,r=(document,e.GGSX_PAGES=e.GGSX_PAGES||{});r.pages=r.pages||{},r.blocks=r.blocks||{};var t="Hi GrocerGoSx, provisioning request.\nBoat: \nMarina / berth: \nDeparture date & time: \nGuests & crew: \nList: ";r.pages["/yacht-provisioning"]={blocks:[{type:"hero",img:"0cf27a8746ec4dd887e5a716f301b49b.jpg",alt:"Aerial view of a marina with yachts on turquoise water",eyebrow:"Yacht & charter provisioning",title:"Provisioned and on board before you sail.",lead:"For captains, chefs and charter guests. Send your provisioning list and departure time, and we'll shop the island and deliver to your marina on the Dutch or French side.",ctas:[{t:"Send your provisioning list",wa:t},{t:"Shop the catalogue",href:"/shop-now"}],chips:["Dutch & French marinas","Timed to your departure","Itemised invoice"]},{type:"cards",title:"Built around the boat",sub:"Charter provisioning is its own job, and we treat it that way.",cols:4,items:[{icon:"list",t:"Your list, any format",x:"A spreadsheet, a photo of the chef's notes or a quick message. We confirm quantities, brands and swaps before we shop."},{icon:"clock",t:"Timed to departure",x:"Tell us when you sail and we schedule the run so you're stocked before you cast off."},{icon:"wine",t:"Drinks, ice and spirits",x:"Water, soft drinks, beer, wine, spirits, mixers and ice. Alcohol is supplied to adults 18+ only."},{icon:"receipt",t:"Itemised invoice",x:"Every item on your invoice, so the captain or broker can reconcile the provisioning budget."}]},{type:"split",img:"11062b_83042b7ca3e64eafa83066ac6aac2f0e~mv2.jpeg",alt:"Fresh fruit and drinks laid out on a yacht deck",kicker:"For charter guests",title:"Step aboard to your favourites",text:["Joining a charter? Send us your preferences before you arrive, from snacks and wine to a week of breakfasts, and we'll coordinate the delivery with your captain or broker."],items:["Fresh produce, bakery, deli and pantry","Your favourite brands, wherever the island has them","Special diets and allergies noted on the order"],ctas:[{t:"Send your preferences",wa:"Hi GrocerGoSx, we're joining a charter and would like provisioning.\nBoat: \nMarina: \nDates: \nPreferences: "}]},{type:"marinas",id:"marinas",title:"Marinas we deliver to",sub:"{{Delivery_chip}} to every marina on the island, Dutch side and French side."},{type:"steps",title:"How it works",items:[["Send your list","With the boat name, marina, berth if you have it, and your departure time."],["We confirm by message","Quantities, brands and swaps, plus your total and a secure payment link."],["We shop","Shopped on the day, with anything hard to find confirmed with you first."],["Delivered to your marina","Handed over to the crew, ready to stow."]]},{type:"prices",title:"Same simple pricing",sub:"All prices include applicable taxes.",rows:[["Provisions","GrocerGoSx concierge prices","About {{catalogue_markup}} over the shelf price ({{liquor_markup}} on beer, wine and spirits); on the part of a till receipt above $300, 15%. Restaurant orders and anything you've pre-paid are passed through at exactly what we paid, plus the same service fee."],["Service Fee","{{run_rate}} of your order","{{Fee_min_short}} (standing orders count as booked ahead). Never more than {{service_fee_max}}."],["Delivery","{{delivery_value}}","{{Delivery_how}}. To any marina on the island."],["Taxes","Included","Nothing extra is added at checkout."]],link:["Full pricing & fees","/pricing"]},{type:"faq",title:"Captains often ask",items:[["Can you deliver to a boat at anchor?","We deliver to the marina. If you're anchored out, tell us which dock your tender can reach and we'll meet the crew there."],["How much notice do you need?","As much as you can give, especially for big provisioning lists and in high season. Same-day runs are often possible, so message us to check."],["Can you find specific brands?","Usually. Island supply varies, so we confirm anything hard to find before we shop and suggest the closest match if it's unavailable."],["How do we pay?","We send your total and a secure card payment link before we shop, and you get an itemised invoice for the run."]]},{type:"cta",title:"Sailing soon?",text:"Send your list and departure time: WhatsApp, iMessage or text +590 690 77 9119, or email grocergosx@gmail.com.",ctas:[{t:"Send your provisioning list",wa:t},{t:"Email us",mail:"Provisioning request"}]}]},r.pages["/partners"]={blocks:[{type:"hero",img:"c2a99153f2b44e7a86654564e2f74114.jpg",alt:"A modern villa with a pool and sun deck",eyebrow:"For hosts & property managers",title:"Five-star arrivals, without the extra errands.",lead:"Partner with GrocerGoSx and your guests can have their villa stocked before they land, groceries delivered during their stay and errands taken care of, while you stay focused on your properties.",ctas:[{t:"Become a partner",href:"#join"},{t:"Message Dwayne",wa:"Hi Dwayne, I look after properties in St. Maarten and I'd like to hear about the GrocerGoSx partner programme."}],chips:["Both sides of the island","Your own guest link","Locally owned"]},{type:"cards",title:"What your guests get",cols:4,items:[{icon:"home",t:"A stocked villa on arrival",x:"Groceries, drinks and essentials put away before check-in, with a photo when it's done."},{icon:"bag",t:"Groceries and restaurant pickup",x:"3,000+ supermarket items and island restaurants, delivered during their stay."},{icon:"sun",t:"Errands, laundry and rentals",x:"Pharmacy runs, laundry, rentals and custom requests."},{icon:"chat",t:"Fast, personal replies",x:"Real people on WhatsApp, iMessage or text, with photos to confirm orders."}]},{type:"cards",title:"What you get as a partner",sub:"We share the partner terms on request. [Ask us](#join) and we'll walk you through them.",cols:4,items:[{icon:"star",t:"Partner rate",x:"{{Partner_fee}} on every order for your properties and owners, and for the guests you refer."},{icon:"key",t:"Welcome cards with your QR code",x:"Branded cards for each property, with your own GrocerGoSx link so guests can order in seconds."},{icon:"gift",t:"A thank-you for every referral",x:"Guests who order through your link are tagged to you, and every order they place earns you a referral thank-you."},{icon:"shield",t:"Less on your plate",x:"No more last-minute supply runs for guests. We handle shopping, delivery and access, coordinated with you."}]},{type:"steps",title:"How your partner link works",items:[["We set you up","You get a personal link, like grocergosx.com/?ref=yourname, plus QR welcome cards for each property."],["Guests tap or scan","They land on GrocerGoSx with a welcome from you, and for 30 days their orders are marked as referred by you."],["We look after them","Stocking, groceries and errands for their whole stay, with access arranged through you."],["You're thanked for every order","Your partner rate and referral thank-you, as agreed with you."]]},{type:"split",flip:!0,img:"11062b_28f51d7e7575438db0c28203e4494c00~mv2.jpeg",alt:"A key in the door of a guest room",kicker:"Who it's for",title:"Made for island hospitality",text:["If guests stay in your properties, we can make their stay easier:"],items:["Property managers and villa rental agencies","Airbnb and VRBO hosts","Villa owners who rent out their home","Concierge desks, charter brokers and boutique hotels"]},{type:"partnerForm",id:"join",title:"Become a partner",sub:"Tell us a little about your properties and we'll get back to you with the partner terms."},{type:"quotes",title:"Trusted by owners and guests",items:[["Excellent service. Dwayne confirmed items requested were correct by sending photos and delivered exactly as requested in a timely fashion. Definitely recommend for any villa stay!","Diana McKennon","Villa property owner"],["Grocery and concierge service was perfect! They stayed in touch and we got everything we ordered. Absolute luxury for the convenience - thank you!","Cori Bavis","Airbnb guest"]]},{type:"cta",title:"Questions first?",text:"Message Dwayne directly: WhatsApp, iMessage or text +590 690 77 9119, or email grocergosx@gmail.com.",ctas:[{t:"Message Dwayne",wa:"Hi Dwayne, I have a question about the GrocerGoSx partner programme."},{t:"Email us",mail:"Partner programme"}]}]},r.run&&r.run()}();
} catch (e) { try { console.warn('[GGSX bundle] Pages 4 Texts: Yacht & Partners', e); } catch (e2) {} }
